function statusClass(s=''){s=s.toLowerCase();if(/accepted|submitted|resolved|above|on track|connected|approved|complete|active/.test(s))return'success';if(/review|progress|watch|draft|pending|open/.test(s))return'warning';if(/overdue|blocked|rejected|at risk|high/.test(s))return'danger';if(/medium|info/.test(s))return'info';return'neutral'}
function pill(s,c){return `<span class="status ${c||statusClass(s)}">${escapeHTML(s)}</span>`}
function pageHead(title,desc,actions='',eyebrow='INVESTEE PORTAL'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function btn(label,action,kind='',ic='',attrs=''){return `<button class="btn ${kind}" data-action="${action}" ${attrs}>${ic?icon(ic):''}<span class="btn-label">${label}</span></button>`}
function metricCard(m){return `<div class="card metric ${m.tone||''}"><div class="metric-top"><div class="metric-icon">${icon(m.icon)}</div>${m.badge||''}</div><div class="metric-label">${m.label}</div><div class="metric-value mono">${m.value}</div><div class="metric-foot">${m.trend?`<span class="trend ${m.trend}">${m.trend==='up'?'↗':'↘'}</span>`:''}<span>${m.foot}</span></div></div>`}
function sparkline(values,colour='var(--brand)',fill='none'){const w=190,h=46,p=4,min=Math.min(...values),max=Math.max(...values),pts=values.map((v,i)=>`${p+i*(w-p*2)/(values.length-1)},${h-p-(v-min)/(max-min||1)*(h-p*2)}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="${fill}" stroke="${colour}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>`}
function lineChart(series,labels,second=null){const w=700,h=235,p={l:38,r:12,t:14,b:28},all=second?[...series,...second]:series,min=Math.min(...all)*.9,max=Math.max(...all)*1.08,x=i=>p.l+i*(w-p.l-p.r)/(series.length-1),y=v=>p.t+(max-v)/(max-min||1)*(h-p.t-p.b),path=s=>s.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');let grid='';for(let i=0;i<5;i++){const yy=p.t+i*(h-p.t-p.b)/4;const val=max-i*(max-min)/4;grid+=`<line class="chart-grid" x1="${p.l}" y1="${yy}" x2="${w-p.r}" y2="${yy}"/><text class="chart-label" x="2" y="${yy+3}">${val.toFixed(val<10?1:0)}</text>`}let xl=labels.map((l,i)=>`<text class="chart-label" text-anchor="middle" x="${x(i)}" y="${h-7}">${l}</text>`).join('');return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--brand)" stop-opacity=".2"/><stop offset="1" stop-color="var(--brand)" stop-opacity="0"/></linearGradient></defs>${grid}${xl}<path class="chart-area" d="${path(series)} L${x(series.length-1)},${h-p.b} L${x(0)},${h-p.b} Z"/><path class="chart-line" d="${path(series)}"/>${series.map((v,i)=>`<circle class="chart-dot" cx="${x(i)}" cy="${y(v)}" r="3"/>`).join('')}${second?`<path d="${path(second)}" fill="none" stroke="var(--emerald)" stroke-width="2.2" stroke-dasharray="6 4" stroke-linecap="round"/>`:''}</svg>`}
function barChart(values,labels,colour='var(--brand)'){const w=700,h=220,p={l:34,r:12,t:10,b:30},max=Math.max(...values)*1.15,bw=(w-p.l-p.r)/values.length*.52;let grid='';for(let i=0;i<5;i++){const yy=p.t+i*(h-p.t-p.b)/4;grid+=`<line class="chart-grid" x1="${p.l}" y1="${yy}" x2="${w-p.r}" y2="${yy}"/>`}return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}${values.map((v,i)=>{const x=p.l+(i+.5)*(w-p.l-p.r)/values.length-bw/2;const bh=v/max*(h-p.t-p.b);return `<rect x="${x}" y="${h-p.b-bh}" width="${bw}" height="${bh}" rx="5" fill="${colour}" opacity="${.68+i*.05}"/><text class="chart-label" text-anchor="middle" x="${x+bw/2}" y="${h-8}">${labels[i]}</text>`}).join('')}</svg>`}
