 if(a==='forecast-readonly-cell'){state.activeForecastCell=el.dataset.address;const name=$('#forecastNameBox'),bar=$('#forecastFormulaBar');if(name)name.value=state.activeForecastCell;if(bar){bar.value=el.dataset.formula||el.textContent.trim();bar.readOnly=true;bar.placeholder='Locked historical actual'}$$('.forecast-value.active').forEach(x=>x.classList.remove('active'));el.closest('.forecast-value')?.classList.add('active');return}
 if(a==='submit-report')return submitReportModal();
 if(a==='report-detail')return reportDetail(el.dataset.id);
