 if(a==='preview-document')return previewDocumentModal(el.dataset.document||$('#drawerTitle')?.textContent||'Document');
 if(a==='preview-zoom-in'||a==='preview-zoom-out'){const page=$('#previewPage'),label=$('#previewZoom');if(!page||!label)return;let z=Number(page.dataset.zoom||1);z=Math.max(.7,Math.min(1.5,z+(a==='preview-zoom-in'?0.1:-0.1)));page.dataset.zoom=z;page.style.transform=`scale(${z})`;label.textContent=Math.round(z*100)+'%';return}
 if(a==='print-preview'){window.print();return}
